// Simple Asteroid Dodge game targeting <canvas id="game"></canvas>
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.offsetWidth;
  const height = canvas.height = canvas.offsetHeight;

  // Ship
  const ship = {x: width/2, y: height - 30, w: 20, h: 30, fuel: 100};
  // Input handling
  let mouseX = ship.x;
  canvas.addEventListener('mousemove', e => {
    const rect = canvas.getBoundingClientRect();
    mouseX = e.clientX - rect.left;
  });
  const keys = {};
  window.addEventListener('keydown', e => keys[e.key] = true);
  window.addEventListener('keyup', e => keys[e.key] = false);

  // Asteroids & fuel pickups
  const asteroids = [];
  const fuels = [];
  let frame = 0;
  let score = 0;
  let gameOver = false;

  function spawnAsteroid() {
    const size = 20 + Math.random()*30;
    asteroids.push({x: Math.random()*(width-size), y: -size, size, speed: 2 + Math.random()*2});
  }
  function spawnFuel() {
    const size = 12;
    fuels.push({x: Math.random()*(width-size), y: -size, size, speed: 2});
  }

  function update(dt) {
    // ship movement
    if (keys.ArrowLeft) ship.x -= 200*dt;
    if (keys.ArrowRight) ship.x += 200*dt;
    ship.x += (mouseX - ship.x) * 0.1; // smooth follow
    ship.x = Math.max(0, Math.min(width - ship.w, ship.x));
    // fuel consumption
    ship.fuel -= dt * 5; // per second
    if (ship.fuel <= 0) gameOver = true;

    // spawn asteroids/fuel
    if (frame % 60 === 0) spawnAsteroid();
    if (frame % 300 === 0) spawnFuel();

    // update asteroids
    asteroids.forEach(a => a.y += a.speed);
    fuels.forEach(f => f.y += f.speed);
    // remove off‑screen
    while (asteroids.length && asteroids[0].y > height) asteroids.shift();
    while (fuels.length && fuels[0].y > height) fuels.shift();

    // collision
    for (const a of asteroids) {
      if (a.x < ship.x + ship.w && a.x + a.size > ship.x && a.y < ship.y + ship.h && a.y + a.size > ship.y) {
        gameOver = true; break;
      }
    }
    for (let i = fuels.length-1; i>=0; i--) {
      const f = fuels[i];
      if (f.x < ship.x + ship.w && f.x + f.size > ship.x && f.y < ship.y + ship.h && f.y + f.size > ship.y) {
        ship.fuel = Math.min(100, ship.fuel + 30);
        fuels.splice(i,1);
      }
    }
    score += dt * 10;
  }

  function draw() {
    ctx.clearRect(0,0,width,height);
    // ship
    ctx.fillStyle = '#0f0';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // asteroids
    ctx.fillStyle = '#888';
    asteroids.forEach(a => ctx.fillRect(a.x, a.y, a.size, a.size));
    // fuel pickups
    ctx.fillStyle = '#ff0';
    fuels.forEach(f => ctx.fillRect(f.x, f.y, f.size, f.size));
    // UI
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Fuel: ' + Math.ceil(ship.fuel), 10, 20);
    ctx.fillText('Score: ' + Math.floor(score), 10, 40);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0,0,width,height);
      ctx.fillStyle = '#f00';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width/2, height/2);
    }
  }

  let last = performance.now();
  function loop(now) {
    const dt = (now - last) / 1000;
    last = now;
    if (!gameOver) update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
